const fs = require('fs');
const path = require('path');

const inputPath = path.join(__dirname, 'input.json');
const outputPath = path.join(__dirname, 'answer.json');

const input = JSON.parse(fs.readFileSync(inputPath, 'utf8'));
const { quantity, unitPrice } = input;

if (typeof quantity !== 'number' || typeof unitPrice !== 'number') {
  throw new TypeError(`quantity/unitPrice must be numbers, got: ${JSON.stringify(input)}`);
}

const total = quantity * unitPrice;
fs.writeFileSync(outputPath, JSON.stringify({ total }, null, 2) + '\n', 'utf8');
console.log(`total = ${quantity} * ${unitPrice} = ${total}`);

